interface PageContent {
  title?: string;
  description?: string;
  slug: string;
  excerpt?: string;
  coverImage?: string;
  updatedAt?: string;
}

interface SiteConfig {
  siteName: string;
  baseUrl: string;
  defaultDescription: string;
  defaultOgImage: string;
  twitterHandle?: string;
}

interface GeneratedMetadata {
  title: string;
  description: string;
  canonicalUrl: string;
  openGraph: {
    'og:title': string;
    'og:description': string;
    'og:url': string;
    'og:type': string;
    'og:image': string;
    'og:site_name': string;
  };
  twitter: {
    'twitter:card': string;
    'twitter:site'?: string;
    'twitter:title': string;
    'twitter:description': string;
    'twitter:image': string;
  };
}

/**
 * Strip HTML tags and escape special characters for attribute inclusion.
 */
function sanitizeText(text: string): string {
  return text
    .replace(/<[^>]*>/g, '') // Strip HTML tags
    .replace(/"/g, '&quot;') // Escape double quotes
    .replace(/'/g, '&#39;') // Escape single quotes
    .replace(/
+/g, ' ')
    .trim();
}

/**
 * Truncate text to target length without cutting words in half.
 */
function truncateText(text: string, maxLength: number = 160): string {
  const sanitized = sanitizeText(text);
  if (sanitized.length <= maxLength) return sanitized;
  return sanitized.slice(0, maxLength).replace(/\s+\S*$/, '') + '...';
}

/**
 * Generate metadata object with complete fallback hierarchy.
 */
export function generatePageMetadata(
  content: PageContent,
  siteConfig: SiteConfig
): GeneratedMetadata {
  const rawTitle = content.title ? content.title.trim() : 'Untitled Page';
  const title = `${sanitizeText(rawTitle)} | ${siteConfig.siteName}`;

  const rawDescription = content.description || content.excerpt || siteConfig.defaultDescription;
  const description = truncateText(rawDescription, 160);

  const canonicalUrl = new URL(content.slug, siteConfig.baseUrl).toString();
  const imageUrl = content.coverImage
    ? new URL(content.coverImage, siteConfig.baseUrl).toString()
    : new URL(siteConfig.defaultOgImage, siteConfig.baseUrl).toString();

  const metadata: GeneratedMetadata = {
    title,
    description,
    canonicalUrl,
    openGraph: {
      'og:title': title,
      'og:description': description,
      'og:url': canonicalUrl,
      'og:type': 'article',
      'og:image': imageUrl,
      'og:site_name': siteConfig.siteName,
    },
    twitter: {
      'twitter:card': 'summary_large_image',
      ...(siteConfig.twitterHandle && { 'twitter:site': siteConfig.twitterHandle }),
      'twitter:title': title,
      'twitter:description': description,
      'twitter:image': imageUrl,
    },
  };

  return metadata;
}

/**
 * Helper to render metadata object into HTML head tag strings.
 */
export function renderMetaTags(metadata: GeneratedMetadata): string {
  const tags: string[] = [
    `<title>${metadata.title}</title>`,
    `<meta name="description" content="${metadata.description}">`,
    `<link rel="canonical" href="${metadata.canonicalUrl}">`,
  ];

  for (const [property, value] of Object.entries(metadata.openGraph)) {
    tags.push(`<meta property="${property}" content="${value}">`);
  }

  for (const [name, value] of Object.entries(metadata.twitter)) {
    tags.push(`<meta name="${name}" content="${value}">`);
  }

  return tags.join('\n');
}

